#pragma once

#include <array>
#include <cstddef>
#include <span>
#include <vector>

namespace miniips::test {

// Documentation-only addresses, fixed TCP HELLO and UDP byte payloads.
inline std::vector<std::byte> tcp_packet() {
    constexpr std::array<unsigned char, 59> data{
        0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88, 0x99, 0xaa, 0xbb,
        0x08, 0x00, 0x45, 0x00, 0x00, 0x2d, 0x12, 0x34, 0x40, 0x00, 0x40, 0x06,
        0x3c, 0x60, 0xc0, 0x00, 0x02, 0x01, 0xc6, 0x33, 0x64, 0x02, 0x30, 0x39,
        0x1f, 0x90, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x50, 0x18,
        0x40, 0x00, 0x40, 0x21, 0x00, 0x00, 0x48, 0x45, 0x4c, 0x4c, 0x4f
    };
    const auto bytes = std::as_bytes(std::span{data});
    return {bytes.begin(), bytes.end()};
}

inline std::vector<std::byte> udp_packet() {
    constexpr std::array<unsigned char, 45> data{
        0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88, 0x99, 0xaa, 0xbb,
        0x08, 0x00, 0x45, 0x00, 0x00, 0x1f, 0x12, 0x34, 0x40, 0x00, 0x40, 0x11,
        0x3c, 0x63, 0xc0, 0x00, 0x02, 0x01, 0xc6, 0x33, 0x64, 0x02, 0x00, 0x35,
        0xd4, 0x31, 0x00, 0x0b, 0xa7, 0xeb, 0x44, 0x4e, 0x53
    };
    const auto bytes = std::as_bytes(std::span{data});
    return {bytes.begin(), bytes.end()};
}

}  // namespace miniips::test
